insert into public.desk_rules (rule_id, title, purpose, mechanism, owner_paths, status, verdict, ruling_summary, growth_cost, ruin_risk_reduction, statistics_note, gaming_analysis, interactions, needs_david, ruling_file, ruling_date, next_review_date) values
  ('starter-stake', 'Starter stake for unproven theses (equal 3% book risk per bet)', 'Lets an unproven thesis trade (learning comes from trade count, not size) without a big loss before there is evidence.', 'starter = 0.03 x current book / steward bet volatility (`private.steward_bet_vol`: sd of return on stake over the steward''s closed priced non-paper trades, floored at 0.25; 1.0 while n < 5), x the steward drawdown scale. On 2026-09-26: QUANTANAMO sd 0.222 -> floor 0.25 -> 12% of book = $660; BANDIT sd 0.449 -> 6.68% = 0.1205 SOL (x0.987 = 0.119); ODDSBORNE sd 1.957 -> 1.53% = $4.24 (x0.5 = $2.12). History: fixed dollars ($250 / $15 / 0.10 SOL) until migration 37, then the same as a book share until migration 41.', array['supabase/schemas/22_edge_scaled_stake.sql', 'supabase/schemas/37_court_rulings.sql', 'supabase/schemas/41_court_decisions.sql']::text[], 'in_force', 'amend', 'Amend (shipped in two steps): book share, not fixed dollars (37); level set to equal risk per bet at v = 3% (41, decided 2026-09-26 by the parent agent under David''s delegation). The 0.25 sd floor stops a lucky low-variance sample from inflating the starter (max starter 12% of book). Amendment: starter = 0.03 x book / max(steward sd of return on stake, 0.25) (1.0 while the steward has < 5 trades), x drawdown scale. Proven theses keep half-Kelly on the LCB, never below the starter.', 'Negative for QUANTANAMO ($250 -> $660: MC P(2x) at Sharpe 0.2 rises from 44.7% toward the v = 3-4% range); ODDSBORNE smaller ($15 -> $4.24 before scale).', 'ODDSBORNE zero-edge P(DD50) 50.8% at 5.4% of book vs ~1-2% at v = 3-4%; QUANTANAMO P(DD50) stays <= 1.5% with gap stress.', 'The starter should be calibrated to stake volatility, not a flat %. A vol-normalized starter, stake = v x book / sd(return on stake), gives every steward the same book risk per unproven bet.', 'With a flat %, the steward whose instruments are most volatile gets the most book risk per bet (ODDSBORNE). Vol-normalizing removes that tilt.', 'edge-max-stake, drawdown-scaling.', false, 'docs/rules/starter-stake.md', '2026-09-26'::date, '2026-10-10'::date),
  ('new-thesis-escape', 'New-thesis escape from a loss-reduced cap', 'The problem: per-thesis halving could be escaped by registering a new thesis. The first fix (steward-wide cap on every unproven thesis, #97) pinned QUANTANAMO themes at $62.50 and was reverted (#98).', 'Resolved structurally. Loss halving is struck, and the only loss response is steward-wide drawdown scaling, which applies to every thesis, new or old. A new thesis gets the starter x the steward''s drawdown scale, the same as any unproven thesis.', array['supabase/schemas/34_revert_steward_wide_starter.sql', 'supabase/schemas/37_court_rulings.sql', 'supabase/schemas/41_court_decisions.sql']::text[], 'repealed', 'strike', 'Strike the problem at its root (no per-thesis punishment exists to escape). No separate rule needed. Amendment: None beyond loss-streak-halving and drawdown-scaling.', 'None.', 'Via drawdown-scaling.', 'Punishing unrelated theses for one thesis''s streak treats noise as signal.', 'The remaining gap (a new QUANTANAMO thesis stated at >= 80 passed the gate with zero evidence) is closed by migration 41: the gate reads only the results score, and a thesis with < 3 effective trades is unscored and needs David. See quantanamo-80-gate.', 'loss-streak-halving, drawdown-scaling, quantanamo-80-gate.', false, 'docs/rules/new-thesis-escape.md', '2026-09-26'::date, '2026-10-26'::date),
  ('outcome-rescore-confidence', 'Results re-score of thesis confidence (expected return per trade)', 'Tempers a steward''s stated confidence with realized outcomes. Feeds the QUANTANAMO >= 80 gate and hardening/forming status.', '`private.thesis_results_score`: n_eff = live trades + min(0.5 x backtest n, 20); mean_eff pools the live mean return on stake with the backtest mean haircut 50%; sd_eff = max(pooled sd, 0.25); results_confidence = round(100 x Phi(mean_eff / (sd_eff / sqrt(n_eff)))) when n_eff >= 3, else null (unscored). Demote hardening -> forming only when the live upper bound mean + max(sd, 0.25)/sqrt(n) < 0, or n >= 10 with mean < 0; kill only when n >= 10 and the upper bound < 0. theses.confidence (display) = results_confidence when scored, else the stated number. Only the re-score writes the results columns (guard trigger). Was: Beta on hit rate, cap 60 and demote at n >= 5 with negative P/L.', array['supabase/schemas/11_outcome_rescore_sizing.sql', 'supabase/schemas/41_court_decisions.sql']::text[], 'in_force', 'amend', 'Amend (shipped in migration 41; decided 2026-09-26 by the parent agent under David''s delegation). Status changes on the 2026-09-26 re-run: none (no thesis has a negative upper bound or n >= 10). Amendment: Score on expected return per trade (above). Stated confidence is display only.', 'Removes the permanent block on asymmetric theses.', 'Demotion/kill now needs real evidence of negative edge.', 'Five trades can''t tell a Sharpe-0.1 thesis from zero: P(sum < 0) = Phi(-0.1 sqrt 5) = 41%. A hit-rate Beta prior ignores payoff asymmetry.', 'Pushes a steward toward high-hit-rate, low-payoff trades (take profits early, let losers run) just to keep confidence high: the opposite of what compounds.', 'quantanamo-80-gate, edge-max-stake, backtest-evidence-credit.', false, 'docs/rules/outcome-rescore-confidence.md', '2026-09-26'::date, '2026-10-26'::date),
  ('quantanamo-80-gate', 'QUANTANAMO autonomous-entry gate: hardening thesis with results score >= 80', 'David approves anything below 80; autonomy only for strong theses.', '`steward_sizing_guidance`: QUANTANAMO entry_allowed needs status = hardening and theses.results_confidence >= 80 (reason `quantanamo_unscored` when unscored, else `quantanamo_confidence_gate`). Backtest credit maps to a score through the same math: a thesis with only backtest evidence has n_eff = min(0.5 x n_bt, 20) (>= 3 needs n_bt >= 6) and scores Phi(0.5 x mean_bt / (max(sd_bt, 0.25) / sqrt(n_eff))); passing 80 needs z >= 0.84, e.g. at full weight (n_bt >= 40) and sd 0.25 a backtest mean >= 9.4% per trade.', array['supabase/schemas/22_edge_scaled_stake.sql', 'supabase/schemas/41_court_decisions.sql', 'docs/scheduled-run-prompt.md']::text[], 'in_force', 'amend', 'Amend (shipped in migration 41; decided 2026-09-26 by the parent agent under David''s delegation): the 80 threshold stays, but it reads the results score only. On 2026-09-26 no thesis passes: neocloud_compute (1 trade) and semis_photonics (0) are unscored, earnings_gap_structure scores 56; every QUANTANAMO entry needs David until a thesis earns >= 80 or gets qualifying backtest credit. Amendment: Gate on results_confidence >= 80; unscored (< 3 effective trades) fails and asks David; stated confidence is display only.', 'Autonomy now waits for evidence (David approves meanwhile).', 'Closes the self-stated-85 path to autonomy.', 'Before 41, at n = 0 the gate read the steward''s self-stated number (80 was a claim, not a measurement). Now 80 means P(expected return per trade > 0) >= 0.8 on at least 3 effective trades (z >= 0.84, close to the 1-sigma LCB > 0 that proves an edge for sizing).', 'Before 41 a steward could state 85 on a brand-new thesis and pass, and couldn''t earn 80 with an asymmetric winner. Now stated numbers can''t open the gate, the results columns are write-protected (only the re-score writes them), and an asymmetric winner earns its score from expectancy.', 'outcome-rescore-confidence, new-thesis-escape, backtest-evidence-credit.', false, 'docs/rules/quantanamo-80-gate.md', '2026-09-26'::date, '2026-10-26'::date),
  ('portfolio-exposure', 'Portfolio exposure: open risk to invalidation <= 10% of book', 'Per-entry caps don''t bound total or correlated exposure across open lots.', '`private.steward_open_risk`: open risk = sum over open lots of qty x max(mark - invalidation_price, 0) in the book unit (no invalidation: full qty x mark; unmarked: 0, flagged). Budget 10% of book. Guidance (6th arg p_entry_price) sizes a new entry to fit: min(requested, max_stake, cash, headroom / ((entry - invalidation) / entry)); without an entry price the whole notional counts as risk; no headroom -> `exposure_cap`. `public.v_exposure_usage` and v_ledger_watchdog (`exposure_over_budget`, `exposure`) report usage.', array['supabase/schemas/41_court_decisions.sql']::text[], 'in_force', 'amend', 'Enact option (b) at R = 10% (migration 41; decided 2026-09-26 by the parent agent under David''s delegation). On enactment QUANTANAMO is at 11.9% and new entries are blocked (`exposure_cap`) until risk falls (exits, or raising invalidations toward marks); ODDSBORNE and BANDIT have no open lots (0%). Amendment: Open risk to invalidation <= 10% of book per steward; guidance sizes down or blocks.', 'Caps stacking; at a 10% invalidation distance it still allows ~100% of book in positions.', 'Bounds the loss if every open lot hits its invalidation at once to 10% of book (gaps excepted).', 'Needs a correlation estimate by theme; with n this small, use theme membership as the proxy.', 'Without it, a steward can stack correlated starters across several theses.', 'cash-only-no-margin, required-invalidation, edge-max-stake.', false, 'docs/rules/portfolio-exposure.md', '2026-09-26'::date, '2026-10-26'::date)
